def minimumCost(target, words, costs):
    n = len(target)
    MOD = (1 << 61) - 1
    BASE = 911382323
    INF = float('inf')

    # Prefix hashes of target: hash(target[i:j]) = (pre[j] - pre[i] * BASE^(j-i)) % MOD
    pre = [0] * (n + 1)
    for i, ch in enumerate(target):
        pre[i + 1] = (pre[i] * BASE + ord(ch)) % MOD

    # Group words by length: length -> {hash of word: cheapest cost}
    groups = {}
    for w, c in zip(words, costs):
        h = 0
        for ch in w:
            h = (h * BASE + ord(ch)) % MOD
        d = groups.setdefault(len(w), {})
        if h not in d or c < d[h]:
            d[h] = c
    # Only O(sqrt(total word length)) distinct lengths exist
    items = sorted((L, pow(BASE, L, MOD), d) for L, d in groups.items())

    # dp[i] = min cost to build target[i:]
    dp = [INF] * (n + 1)
    dp[n] = 0  # base case: done

    for i in range(n - 1, -1, -1):
        best = INF
        for L, pw, d in items:
            j = i + L
            if j > n:
                break
            if dp[j] == INF:
                continue
            c = d.get((pre[j] - pre[i] * pw) % MOD)
            if c is not None and c + dp[j] < best:
                best = c + dp[j]
        dp[i] = best

    return dp[0] if dp[0] != INF else -1
